# pure Python, no imports, no I/O, deterministic, exact integer arithmetic, fail-closed

def verify(witness):
    primorials = witness['primorials']
    k_values = witness['k_values']
    assert len(primorials) == len(k_values)

    def factorint_exact(n):
        assert n >= 2
        f = {}
        d = 2
        while d * d <= n:
            while n % d == 0:
                f[d] = f.get(d, 0) + 1
                n = n // d
            d += 1
        if n > 1:
            f[n] = f.get(n, 0) + 1
        for e in f.values():
            assert e >= 1
        return f

    def phi(n):
        if n == 1:
            return 1
        r = n
        for p, e in factorint_exact(n).items():
            assert r % p == 0
            r = r // p * (p - 1)
        assert r >= 1
        return r

    def first_k_primes(k):
        primes = []
        c = 2
        while len(primes) < k:
            is_prime = True
            for p in primes:
                if p * p > c:
                    break
                if c % p == 0:
                    is_prime = False
                    break
            if is_prime and all(c % p != 0 for p in primes):
                primes.append(c)
            c += 1
        return primes

    for k, m_expected in zip(k_values, primorials):
        primes = first_k_primes(k)
        assert len(primes) == k
        m = 1
        for p in primes:
            m *= p
        assert m == m_expected, 'primorial mismatch at k=%d' % k
        # exhaustive enumeration justified by proved bound phi(n) >= sqrt(n/2) => n <= 2*m^2
        bound = 2 * m * m
        least = None
        for n in range(1, bound + 1):
            if phi(n) == m:
                least = n
                break
        assert least is not None, 'no preimage in window at k=%d' % k
        assert least == m, 'min preimage != primorial at k=%d' % k

    assert phi(2310) == 480, 'phi(2310) != 480'
    return True
